from pathlib import Path
BASE=Path('.')
def head(title,desc,prefix):
 return f'''<!doctype html><html lang="en-AU"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="{desc}"><title>{title} — Three AM Web + IT</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="{prefix}styles.css"></head><body><a class="skip-link" href="#main">Skip to content</a>'''
def header(prefix):
 return f'''<header class="site-header"><div class="shell header-inner"><a class="brand" href="{prefix}index.html" aria-label="Three AM home"><img src="{prefix}audit/assets/original-path/wp-content/uploads/2019/09/logo-dark.webp" alt="Three AM Web + IT"></a><nav class="desktop-nav" aria-label="Primary navigation"><a href="{prefix}services/index.html">Services</a><a href="{prefix}web/index.html">Web</a><a href="{prefix}portfolio/index.html">Work</a><a href="{prefix}about/index.html">About</a><a href="{prefix}news/index.html">News</a></nav><a class="header-contact" href="{prefix}contact/index.html">Start a conversation <span>↗</span></a><button class="menu-button" type="button" aria-expanded="false" aria-controls="mobile-menu"><span></span><span></span><span></span><span class="sr-only">Open menu</span></button></div><nav id="mobile-menu" class="mobile-nav" aria-label="Mobile navigation" hidden><a href="{prefix}services/index.html">Services</a><a href="{prefix}web/index.html">Web</a><a href="{prefix}portfolio/index.html">Work</a><a href="{prefix}about/index.html">About</a><a href="{prefix}news/index.html">News</a><a href="{prefix}contact/index.html">Contact</a></nav></header>'''
def footer(prefix):
 return f'''<footer class="site-footer"><div class="shell"><div class="footer-top"><a class="brand brand-footer" href="{prefix}index.html"><img src="{prefix}audit/assets/original-path/wp-content/uploads/2019/09/logo-dark.webp" alt="Three AM Web + IT"></a><p>Web, IT, hosting and design —<br>all in one place.</p><a class="footer-email" href="mailto:info@threeam.com.au">info@threeam.com.au <span>↗</span></a></div><div class="footer-links"><div><p>Visit</p><address>Level 1, 105 Churchill Road<br>Prospect 5082<br>Adelaide, South Australia</address></div><div><p>Services</p><a href="{prefix}services/index.html">All services</a><a href="{prefix}web/index.html">Web</a><a href="/it/">IT</a><a href="/hosting/">Hosting</a></div><div><p>Company</p><a href="{prefix}portfolio/index.html">Portfolio</a><a href="{prefix}about/index.html">About us</a><a href="{prefix}news/index.html">News</a><a href="{prefix}contact/index.html">Contact</a></div><div><p>Support</p><a href="/support/">Remote support</a><a href="/pay-invoice/">Pay an invoice</a><a href="{prefix}payment-policy/index.html">Payment policy</a></div></div><div class="footer-bottom"><span>© 2026 Three AM Web + IT</span><div><a href="/terms-and-conditions/">Terms</a><a href="{prefix}payment-policy/index.html">Payment policy</a><a href="/whistleblower-policy/">Whistleblower policy</a></div></div></div></footer><script src="{prefix}script.js"></script></body></html>'''
def hero(crumb,eyebrow,title,intro):
 b=' / '.join(crumb)
 return f'''<section class="page-hero"><div class="shell"><nav class="breadcrumbs" aria-label="Breadcrumb">{b}</nav><p class="eyebrow light"><span></span> {eyebrow}</p><h1>{title}</h1><p class="intro">{intro}</p></div></section>'''
def page(path,title,desc,content,prefix='../'):
 p=Path(path);p.parent.mkdir(parents=True,exist_ok=True);p.write_text(head(title,desc,prefix)+header(prefix)+f'<main id="main">{content}</main>'+footer(prefix))
# About
page('about/index.html','About Us','Learn about Three AM Web + IT, an Adelaide family business.',hero(['<a href="../index.html">Home</a>','<span aria-current="page">About</span>'],'About Three AM','A family business who value trust and quality.','A family business who value trust and quality.')+'''<section class="section"><div class="shell content-grid"><aside class="side-nav"><p>About Three AM</p><a href="#why">Why choose us <span>↓</span></a><a href="#story">Our early days <span>↓</span></a><a href="../contact/index.html">Contact <span>↗</span></a></aside><div class="prose"><h2 id="why">Quality connections, built personally.</h2><p>Our core values of quality, trust, and a personalised service are entrenched in everything we do. We consistently produce great outcomes and great value for our clients that help them build their businesses.</p><h3>Our vision</h3><p>“Shaping a healthy future as a highly respected and trusted industry professional”.</p><h3>What we do</h3><p>Three AM helps build businesses by creating quality connections with audiences through web, IT and design solutions. We offer web design, web development, web maintenance, hosting, IT support, graphic design, and related consulting and marketing services.</p><h2 id="story">Working at 3:00am</h2><p>The name comes from the early days. Working part-time nightfill jobs, founders Simon and Scott Gill would often come home around 3am and start coding and designing. Some of their best ideas were generated at that time of the morning, so the name stuck.</p><p>In 2005, Scott and Simon were busy building websites for friends and family when they decided it was time they did it properly. Three AM was official.</p></div></div></section>''')
