page('portfolio/index.html','Portfolio','A selection of Three AM website, branding and design work.',hero(['<a href="../index.html">Home</a>','<span aria-current="page">Portfolio</span>'],'Selected work','A small selection of our work.','A selection of website development, branding and design work from Three AM.')+f'''<section class="section"><div class="shell"><div class="split-heading"><div><p class="eyebrow"><span></span> Recent work</p><h2>Work that works <em>harder.</em></h2></div></div><div class="tile-grid">{tiles}</div></div></section>''')
