Path('404.html').write_text(head('Page Not Found','The page you requested could not be found.','')+header('')+'''<main id="main"><section class="error-hero"><div class="shell"><p class="eyebrow"><span></span> Page not found</p><h1>404</h1><p>That page has moved, changed, or isn’t here anymore.</p><a class="button button-primary" href="index.html">Back to home <span>→</span></a></div></section></main>'''+footer(''))
